/**
 * The CSV export — recipes only, and WIDE ENOUGH FOR THE LONGEST ONE.
 *
 * WHY THIS IS ITS OWN MODULE: the export's WIDTH is the whole argument. Section 7b records it, and the
 * author's own words are the reason:
 *
 *   "Export: no cap, ever. An earlier draft proposed a fixed SQL view with 10 columns. That is a cap
 *    baked into the schema and was correctly rejected -- 'i dont want to truncate recipees just because
 *    they have 10000 ingredients, thats the nature of tiki drinks and we love them.' The export is
 *    therefore GENERATED BY CODE, NOT DECLARED: its width is computed as `max(ingredient_count)` over
 *    the exported set, so a 12-ingredient Rum Barrel gets 12 columns and a 20-ingredient punch tomorrow
 *    gets 20. The child table has no width at all -- only the exported file is wide, and only for the
 *    length of one file."
 *
 * So there is no constant in this file that says how many ingredient columns there are. `columnsFor`
 * counts, and the count is whatever the data says. A fixed width here would be exactly the cap that was
 * rejected, just moved from the schema into the client.
 *
 * WHAT IT CARRIES, from section 7b: "name, ingredients and amounts, garnish, method, Notes, glass, ice,
 * and NO IMAGE INFO". The last one is a decision rather than an omission -- the artwork is the
 * compositor's, it is not data the author wrote, and a path in a CSV is a broken path on the next
 * machine.
 *
 * RECIPES ONLY, which is why this takes specs and not votes. Section 7b again: "The CSV export stays
 * recipes-only." A visitor's votes are a different artifact with a different question, and mixing them
 * would make one file answer two things badly.
 *
 * NO IMPORTS, AND RUNNABLE DIRECTLY UNDER NODE (`node src/lib/exportCsv.ts`), the same rule as the rest
 * of `src/lib`.
 */

/** One recipe as the export sees it. Amounts stay strings -- `types/roast.ts` says an amount is a label. */
export type ExportSpec = {
  name: string;
  glass: string;
  ice: string;
  method: string;
  notes: string;
  garnish: string;
  ingredients: { name: string; amount: string }[];
};

/** The fixed columns, before the wide part. */
const FIXED = ["name", "glass", "ice", "method", "notes", "garnish"] as const;

/**
 * How many ingredient columns the file needs: THE LONGEST RECIPE IN IT, and nothing else.
 *
 * An empty set is zero, which produces a header with no ingredient columns at all -- correct, and
 * better than a guessed minimum that would imply recipes have a floor they do not have.
 */
export function ingredientWidth(specs: ExportSpec[]): number {
  return specs.reduce((widest, spec) => Math.max(widest, spec.ingredients.length), 0);
}

/**
 * The header row, as an array.
 *
 * PAIRS, NOT TWO BLOCKS. `ingredient_1, amount_1, ingredient_2, amount_2` keeps a name beside its
 * amount, so a row can be read left to right without counting columns. Two separate blocks would make
 * the file narrower to read and impossible to eyeball.
 */
export function columnsFor(specs: ExportSpec[]): string[] {
  const width = ingredientWidth(specs);
  const columns: string[] = [...FIXED];
  for (let n = 1; n <= width; n++) {
    columns.push(`ingredient_${n}`, `amount_${n}`);
  }
  return columns;
}

/**
 * One field, escaped.
 *
 * THE RULE IS RFC 4180 AND IT IS NOT OPTIONAL HERE. A recipe name contains commas ("Rum Barrel, the
 * long one"), a method contains newlines (the corpus is full of them), and a quote appears in real
 * names. A field is quoted when it holds a comma, a quote, a newline or a carriage return, and an
 * embedded quote is DOUBLED. Getting this wrong does not corrupt one cell -- it shifts every column
 * after it for that row, which is the kind of break nobody notices until they open the file.
 */
export function escapeField(value: string): string {
  const text = value ?? "";
  if (/[",\r\n]/.test(text)) {
    return `"${text.replace(/"/g, '""')}"`;
  }
  return text;
}

/** One spec as a row of exactly `columnsFor(specs).length` fields, padded with empties. */
function rowFor(spec: ExportSpec, width: number): string[] {
  const row: string[] = [spec.name, spec.glass, spec.ice, spec.method, spec.notes, spec.garnish];
  for (let n = 0; n < width; n++) {
    const line = spec.ingredients[n];
    row.push(line ? line.name : "", line ? line.amount : "");
  }
  return row;
}

/**
 * The whole file, as a string.
 *
 * A BOM IS PREPENDED, because the project's own CSVs are written `utf-8-sig` and Excel needs it to read
 * `Crème de Menthe` and `jalapeño` as text rather than as mojibake. It is one character, and its absence
 * is the difference between an export that opens and one that has to be explained.
 *
 * CRLF LINE ENDINGS, matching RFC 4180 and the rest of this project's CSVs.
 */
export function csv(specs: ExportSpec[]): string {
  const columns = columnsFor(specs);
  const width = ingredientWidth(specs);
  const lines: string[] = [columns.map(escapeField).join(",")];
  for (const spec of specs) {
    lines.push(rowFor(spec, width).map(escapeField).join(","));
  }
  return "\ufeff" + lines.join("\r\n") + "\r\n";
}

// ── direct run ───────────────────────────────────────────────────────────────────────────────

/**
 * Direct-run detection, without an import. `node:url`'s pathToFileURL would be the obvious way to
 * compare `import.meta.url` with `process.argv[1]`, and importing it would break the zero-import rule
 * that lets this file run at all. The browser never reaches it — `process` is undefined there, which is
 * also why the block below is inert inside the app bundle.
 */
function isDirectRun(): boolean {
  if (typeof process === "undefined" || !process.argv || process.argv.length < 2) return false;
  const entry = process.argv[1];
  const self = import.meta.url.replace(/^file:\/\//, "").replace(/^\/([A-Za-z]:)/, "$1");
  return decodeURIComponent(self).replace(/\\/g, "/") === entry.replace(/\\/g, "/");
}

if (isDirectRun()) {
  // Every check throws, so a wrong answer exits non-zero: the run's output is the evidence.
  let checks = 0;
  const check = (ok: boolean, what: string): void => {
    checks++;
    if (!ok) throw new Error(`export self-check failed: ${what}`);
  };
  const block = (text: string): void => {
    console.log();
    console.log(text);
  };

  const spec = (name: string, n: number, over: Partial<ExportSpec> = {}): ExportSpec => ({
    name,
    glass: "Coupe glass",
    ice: "",
    method: "Shake with ice and strain.",
    notes: "",
    garnish: "orange twist",
    ingredients: Array.from({ length: n }, (_, i) => ({ name: `ingredient ${i + 1}`, amount: "1 cl" })),
    ...over,
  });

  // ── 1. THE WIDTH IS THE LONGEST RECIPE, NOT A CONSTANT ─────────────────────────────────────────
  check(ingredientWidth([]) === 0, "no recipes needs no ingredient columns");
  check(ingredientWidth([spec("short", 2)]) === 2, "one two-ingredient recipe needs two");
  check(ingredientWidth([spec("short", 2), spec("rum-barrel", 12)]) === 12, "a 12-ingredient one needs twelve");
  check(ingredientWidth([spec("a", 3), spec("b", 20)]) === 20, "and a 20-ingredient punch needs twenty");
  const wide = columnsFor([spec("short", 2), spec("punch", 20)]);
  check(wide.length === 6 + 20 * 2, `the header is 6 fixed + 20 pairs, got ${wide.length}`);
  check(wide[wide.length - 1] === "amount_20", `and ends at amount_20, got ${wide[wide.length - 1]}`);
  block("the width is max(ingredient_count) over the set -- section 7b's no-cap rule, in code");

  // ── 2. NO CAP MEANS NO CAP ────────────────────────────────────────────────────────────────────
  const absurd = columnsFor([spec("tiki", 10000)]);
  check(absurd.length === 6 + 20000, `a 10,000-ingredient recipe produces 10,000 pairs, got ${absurd.length - 6}`);
  check(ingredientWidth([spec("tiki", 10000)]) === 10000, "and nothing truncates it");
  block("the author's words: 'i dont want to truncate recipees just because they have 10000 ingredients'");

  // ── 3. the fixed columns, in order, and no image info ─────────────────────────────────────────
  check(FIXED.join(",") === "name,glass,ice,method,notes,garnish", "the fixed columns are as section 7b lists them");
  const header = columnsFor([spec("a", 1)]);
  check(header.slice(0, 6).join(",") === "name,glass,ice,method,notes,garnish", "and they come first");
  check(header[6] === "ingredient_1" && header[7] === "amount_1", "then pairs: name beside its amount");
  check(
    !header.some((c) => /image|art|svg|photo|picture|render/i.test(c)),
    "and NO image info -- section 7b's decision, not an omission",
  );
  block("name, glass, ice, method, notes, garnish, then ingredient/amount pairs, and no image info");

  // ── 4. a short recipe is padded, not shifted ──────────────────────────────────────────────────
  const file = csv([spec("short", 1), spec("long", 3)]);
  const rows = file.replace("\ufeff", "").trimEnd().split("\r\n");
  check(rows.length === 3, `a header and two rows, got ${rows.length}`);
  const shortFields = rows[1].split(",");
  check(shortFields.length === 6 + 3 * 2, `the short row still has every column, got ${shortFields.length}`);
  check(shortFields[shortFields.length - 1] === "", "and it is padded with an empty cell");
  check(rows[2].split(",").length === shortFields.length, "both rows are the same width");
  block("a short recipe is padded to the width: an unpadded row shifts every column after it");

  // ── 5. escaping, which is where a CSV actually breaks ─────────────────────────────────────────
  check(escapeField("plain") === "plain", "a plain field is untouched");
  check(escapeField("a,b") === '"a,b"', "a comma forces quoting");
  check(escapeField('say "when"') === '"say ""when"""', "a quote is doubled and the field is quoted");
  check(escapeField("line one\nline two") === '"line one\nline two"', "a newline forces quoting");
  check(escapeField("carriage\rreturn") === '"carriage\rreturn"', "so does a carriage return");
  check(escapeField("") === "", "an empty field is empty, not a pair of quotes");
  const messy = csv([spec("Rum Barrel, the long one", 1, { notes: 'he said "more rum"' })]);
  check(messy.includes('"Rum Barrel, the long one"'), "a comma in the NAME is escaped");
  check(messy.includes('"he said ""more rum"""'), "and a quote in the NOTES is doubled");
  block("RFC 4180 escaping: commas, quotes and newlines -- the failure that shifts every later column");

  // ── 6. the file's shape ───────────────────────────────────────────────────────────────────────
  check(csv([]).startsWith("\ufeff"), "a BOM, so Excel reads the accents");
  check(csv([]).includes("\r\n"), "CRLF line endings");
  check(csv([]).replace("\ufeff", "").trimEnd().split("\r\n").length === 1, "an empty set is a header and nothing else");
  check(csv([spec("a", 1)]).endsWith("\r\n"), "the file ends with a newline");
  const withEmpty = csv([spec("a", 0)]);
  check(withEmpty.replace("\ufeff", "").split("\r\n")[0] === "name,glass,ice,method,notes,garnish", "a recipe with no ingredients needs no pairs");
  block("a BOM, CRLF, and a trailing newline -- the shape the project's own CSVs already use");

  // ── 7. the amount is a LABEL, and survives as written ─────────────────────────────────────────
  const labels = csv([
    spec("odd amounts", 3, {
      ingredients: [
        { name: "Fernet Branca", amount: "1,5 cl" },
        { name: "Espresso", amount: "1" },
        { name: "Soda water", amount: "top" },
      ],
    }),
  ]);
  check(labels.includes('"1,5 cl"'), "a comma-decimal amount is escaped and kept verbatim");
  check(labels.includes(",1,"), "a bare amount is kept as written");
  check(labels.includes(",top"), "and so is 'top'");
  block("amounts are labels, not measurements: '1,5 cl', '1' and 'top' all export as written");

  block(`all ${checks} export checks passed`);
}
